$(function(){
    var $nav = $(".navigation");
    $nav.find("li").has("ul").children("a").addClass("has-ul");
    $nav.find("li").not(".active").has("ul").children("ul").addClass("hidden-ul");
    $nav.find("li.active").has("ul").children("ul").removeClass("hidden-ul").show();
    $nav.find("li.active").has("ul").addClass("open");

    $nav.off("click", "li.has-children > a, li > a.has-ul")
        .on("click", "li.has-children > a, li > a.has-ul", function(e){
            e.preventDefault();
            e.stopPropagation();
            var $a = $(this);
            var $li = $a.closest("li").not(".disabled");
            if(!$li.length){ return false; }
            var $targetUl = $li.children("ul");
            if(!$targetUl.length){ return false; }

            var isOpen = $targetUl.is(":visible") && !$targetUl.hasClass("hidden-ul");
            if(isOpen){
                $li.removeClass("active open");
                $targetUl.stop(true, true).slideUp(220, function(){
                    $(this).addClass("hidden-ul");
                });
            } else {
                $li.siblings("li").has("ul").each(function(){
                    var $sib = $(this);
                    $sib.removeClass("active open");
                    $sib.children("ul").stop(true, true).slideUp(220, function(){
                        $(this).addClass("hidden-ul");
                    });
                });
                $li.addClass("active open");
                $targetUl.removeClass("hidden-ul").stop(true, true).slideDown(220);
            }
            return false;
        });
    $(".nav-tabs a").click(function(i){i.preventDefault();$(this).tab("show");});
});
